#![allow(dead_code)]

mod pvec {
    use std::rc::Rc;

    pub const BITS: u32 = 5;
    pub const WIDTH: usize = 1 << BITS;
    pub const MASK: usize = WIDTH - 1;

    pub enum Node<T> {
        Branch(Vec<Rc<Node<T>>>),
        Leaf(Vec<T>),
    }

    impl<T> Node<T> {
        fn children(&self) -> &Vec<Rc<Node<T>>> {
            match *self {
                Node::Branch(ref c) => c,
                Node::Leaf(_) => unreachable!("branch expected"),
            }
        }
        fn leaf(&self) -> &[T] {
            match *self {
                Node::Leaf(ref v) => v,
                Node::Branch(_) => unreachable!("leaf expected"),
            }
        }
    }

    pub struct Vector<T> {
        size: usize,
        shift: u32,
        root: Rc<Node<T>>,
        tail: Rc<Vec<T>>,
    }

    impl<T> Clone for Vector<T> {
        fn clone(&self) -> Self {
            Vector { size: self.size, shift: self.shift,
                     root: Rc::clone(&self.root), tail: Rc::clone(&self.tail) }
        }
    }
    impl<T> Default for Vector<T> {
        fn default() -> Self { Vector::new() }
    }

    fn new_path<T>(level: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
        if level == 0 { leaf } else { Rc::new(Node::Branch(vec![new_path(level - BITS, leaf)])) }
    }

    fn push_leaf<T>(node: &Rc<Node<T>>, level: u32, toff: usize, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
        debug_assert!(level >= BITS);
        let idx = (toff >> level) & MASK;
        let mut ch: Vec<Rc<Node<T>>> = node.children().clone();
        debug_assert!(idx <= ch.len());
        if idx == ch.len() {
            ch.push(new_path(level - BITS, leaf));
        } else {
            debug_assert!(level > BITS);
            ch[idx] = push_leaf(&ch[idx], level - BITS, toff, leaf);
        }
        Rc::new(Node::Branch(ch))
    }

    impl<T> Vector<T> {
        pub fn new() -> Self {
            Vector { size: 0, shift: BITS,
                     root: Rc::new(Node::Branch(Vec::new())), tail: Rc::new(Vec::new()) }
        }
        pub fn len(&self) -> usize { self.size }
        pub fn size(&self) -> usize { self.size }
        pub fn is_empty(&self) -> bool { self.size == 0 }
        fn tail_off(&self) -> usize { self.size - self.tail.len() }

        fn chunk_for(&self, i: usize) -> (&[T], usize) {
            let toff = self.tail_off();
            if i >= toff { return (&self.tail, toff); }
            let mut node: &Node<T> = &self.root;
            let mut level = self.shift;
            while level > 0 {
                node = &node.children()[(i >> level) & MASK];
                level -= BITS;
            }
            (node.leaf(), i & !MASK)
        }
        pub fn get(&self, i: usize) -> Option<&T> {
            if i >= self.size { return None; }
            let (c, base) = self.chunk_for(i);
            c.get(i - base)
        }
        pub fn iter(&self) -> Iter<T> {
            Iter { v: self, i: 0, chunk: &[], base: 0, end: 0 }
        }
    }

    impl<T: Clone> Vector<T> {
        pub fn push_back(&self, x: T) -> Vector<T> {
            if self.tail.len() < WIDTH {
                let mut t: Vec<T> = Vec::with_capacity(WIDTH);
                t.extend_from_slice(&self.tail);
                t.push(x);
                return Vector { size: self.size + 1, shift: self.shift,
                                root: Rc::clone(&self.root), tail: Rc::new(t) };
            }
            let toff = self.size - WIDTH;
            let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
            let (root, shift) = if (toff >> self.shift) >= WIDTH {
                (Rc::new(Node::Branch(vec![Rc::clone(&self.root), new_path(self.shift, leaf)])),
                 self.shift + BITS)
            } else {
                (push_leaf(&self.root, self.shift, toff, leaf), self.shift)
            };
            let mut t: Vec<T> = Vec::with_capacity(WIDTH);
            t.push(x);
            Vector { size: self.size + 1, shift: shift, root: root, tail: Rc::new(t) }
        }
    }

    impl<T> std::ops::Index<usize> for Vector<T> {
        type Output = T;
        fn index(&self, i: usize) -> &T {
            match self.get(i) {
                Some(r) => r,
                None => panic!("index out of bounds: the len is {} but the index is {}", self.size, i),
            }
        }
    }

    pub struct Iter<'a, T: 'a> {
        v: &'a Vector<T>,
        i: usize,
        chunk: &'a [T],
        base: usize,
        end: usize,
    }
    impl<'a, T> Iterator for Iter<'a, T> {
        type Item = &'a T;
        fn next(&mut self) -> Option<&'a T> {
            if self.i >= self.v.size { return None; }
            if self.i >= self.end {
                let (c, b) = self.v.chunk_for(self.i);
                debug_assert!(!c.is_empty());
                self.chunk = c; self.base = b; self.end = b + c.len();
            }
            let r = &self.chunk[self.i - self.base];
            self.i += 1;
            Some(r)
        }
        fn size_hint(&self) -> (usize, Option<usize>) {
            let n = self.v.size - self.i; (n, Some(n))
        }
    }
    impl<'a, T> ExactSizeIterator for Iter<'a, T> {}
    impl<'a, T> IntoIterator for &'a Vector<T> {
        type Item = &'a T;
        type IntoIter = Iter<'a, T>;
        fn into_iter(self) -> Iter<'a, T> { self.iter() }
    }

    // ---- invariant audit (test-only) ----
    impl<T> Vector<T> {
        pub fn audit(&self) -> Result<(), String> {
            if self.shift < BITS || self.shift % BITS != 0 { return Err("shift".into()); }
            if self.tail.len() > WIDTH { return Err("tail len".into()); }
            if (self.size == 0) != (self.tail.len() == 0) { return Err("tail empty".into()); }
            let toff = self.tail_off();
            if toff % WIDTH != 0 { return Err("toff align".into()); }
            if self.size > 0 && toff != ((self.size - 1) >> BITS) << BITS { return Err("lazy tail".into()); }
            let m = toff >> BITS;
            if m > (1usize << self.shift) { return Err("capacity".into()); }
            if self.shift > BITS && m <= (1usize << (self.shift - BITS)) { return Err("shift minimality".into()); }
            let got = count_leaves(&self.root, self.shift)?;
            if got != m { return Err(format!("leaf count {} != {}", got, m)); }
            Ok(())
        }
    }
    fn count_leaves<T>(n: &Node<T>, level: u32) -> Result<usize, String> {
        match *n {
            Node::Leaf(ref v) => {
                if level != 0 { return Err("leaf at branch level".into()); }
                if v.len() != WIDTH { return Err(format!("partial leaf {}", v.len())); }
                Ok(1)
            }
            Node::Branch(ref c) => {
                if level == 0 { return Err("branch at leaf level".into()); }
                if c.len() > WIDTH { return Err("overfull branch".into()); }
                let cap = 1usize << (level - BITS);
                let mut total = 0;
                for (k, ch) in c.iter().enumerate() {
                    let got = count_leaves(ch, level - BITS)?;
                    if k + 1 < c.len() && got != cap { return Err("non-last child partial".into()); }
                    total += got;
                }
                Ok(total)
            }
        }
    }
}

mod cpp {
    pub enum StoiErr { Invalid, Range }

    pub fn stoi(b: &[u8]) -> Result<i32, StoiErr> {
        let mut i = 0usize;
        while i < b.len() {
            match b[i] { b' ' | 0x09 | 0x0A | 0x0B | 0x0C | 0x0D => i += 1, _ => break }
        }
        let neg = if i < b.len() && b[i] == b'-' { i += 1; true }
                  else if i < b.len() && b[i] == b'+' { i += 1; false } else { false };
        let start = i;
        let mut acc: i64 = 0;
        let mut ovf = false;
        while i < b.len() && b[i] >= b'0' && b[i] <= b'9' {
            if !ovf {
                acc = acc * 10 + (b[i] - b'0') as i64;
                if acc > 4294967296 { ovf = true; }
            }
            i += 1;
        }
        if i == start { return Err(StoiErr::Invalid); }
        let v = if neg { -acc } else { acc };
        if ovf || v < i32::min_value() as i64 || v > i32::max_value() as i64 { return Err(StoiErr::Range); }
        Ok(v as i32)
    }

    pub fn terminate(what: &str) -> ! {
        use std::io::Write;
        let e = std::io::stderr();
        let mut e = e.lock();
        let _ = write!(e, "terminate called after throwing an instance of '{}'\n  what():  stoi\n", what);
        let _ = e.flush();
        std::process::abort();
    }
}

fn run(n: i32) {
    use pvec::Vector;
    let mut v: Vector<i32> = Vector::new();
    let mut i: i32 = 0;
    while i < n { v = v.push_back(i.wrapping_add(1)); i += 1; }
    let mut sum: i32 = 0;
    for x in &v { sum = sum.wrapping_add(*x); }
    println!("{}", sum);
    let mut v2: Vector<i32> = Vector::new();
    for k in 0..v.size() { v2 = v2.push_back(v[k].wrapping_mul(2)); }
    sum = 0;
    for x in &v2 { sum = sum.wrapping_add(*x); }
    println!("{}", sum);
}

