    let mut v: Vector<i32> = Vector::new();
    v.audit().unwrap();
    let mut snaps: Vec<Vector<i32>> = Vec::new();
    let top = 40000usize;
    for i in 0..top {
        v = v.push_back(i as i32);
        if let Err(e) = v.audit() { panic!("audit fail at {}: {}", i + 1, e); }
        if v.len() <= 4200 || (v.len() >= 32700 && v.len() <= 32900) {
            for j in 0..v.len() { assert_eq!(v[j], j as i32, "index at len {}", v.len()); }
            let mut c = 0usize;
            for (j, x) in v.iter().enumerate() { assert_eq!(*x, j as i32); c += 1; }
            assert_eq!(c, v.len());
            assert_eq!(v.iter().len(), v.len());
        }
        if i % 97 == 0 { snaps.push(v.clone()); }
    }
    // persistence: every retained snapshot still holds exactly its prefix
    for s in &snaps {
        s.audit().unwrap();
        assert_eq!(s.iter().count(), s.len());
        assert_eq!(*s.get(s.len() - 1).unwrap(), (s.len() - 1) as i32);
        assert!(s.get(s.len()).is_none());
    }
    // big spot check across two growths
    let mut w: Vector<i32> = Vector::new();
    for i in 0..1_100_000usize { w = w.push_back(i as i32); }
    w.audit().unwrap();
    for j in [0usize, 31, 32, 1023, 1024, 1055, 1056, 1057, 32799, 32800, 32801,
              1048575, 1048576, 1048607, 1048608, 1099999].iter() {
        assert_eq!(w[*j], *j as i32, "spot {}", j);
    }
    assert_eq!(w.iter().count(), 1_100_000);
    println!("SELFTEST_OK snaps={}", snaps.len());
    let _ = top;
}
